let _markdown = "\n\nOverview [#overview]\n\n<FeedbackBlock id=\"9223c3bb1371a0f9\" body=\"Fumadocs OpenAPI uses a <APIPage /> component to render page contents.\">\n  Fumadocs OpenAPI uses a `<APIPage />` component to render page contents.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"153c827a87794774\" body=\"When customising it, the options are split into server/client configs.\">\n  When customising it, the options are split into server/client configs.\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"components/api-page.tsx\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"components/api-page.tsx\">\n      components/api-page.tsx\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"components/api-page.client.tsx\">\n      components/api-page.client.tsx\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"components/api-page.tsx\">\n    ```tsx\n    import { openapi } from '@/lib/openapi';\n    import { createAPIPage } from 'fumadocs-openapi/ui';\n    import client from './api-page.client';\n\n    export const APIPage = createAPIPage(openapi, {\n      client,\n      // server config\n    });\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"components/api-page.client.tsx\">\n    ```tsx\n    'use client';\n    import { defineClientConfig } from 'fumadocs-openapi/ui/client';\n\n    export default defineClientConfig({\n      // client config\n    });\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<FeedbackBlock id=\"2cdc1618a8985e29\" body=\"Installing the types packages is highly recommended for advanced customisations:\">\n  Installing the types packages is highly recommended for advanced customisations:\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"npm\" groupId=\"package-manager\" persist>\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"npm\">\n      npm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"pnpm\">\n      pnpm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"yarn\">\n      yarn\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"bun\">\n      bun\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"npm\">\n    ```bash\n    npm install openapi-types json-schema-typed -D\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"pnpm\">\n    ```bash\n    pnpm add openapi-types json-schema-typed -D\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"yarn\">\n    ```bash\n    yarn add openapi-types json-schema-typed --dev\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"bun\">\n    ```bash\n    bun add openapi-types json-schema-typed --dev\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<FeedbackBlock id=\"927eabb6a164adc6\" body=\"It gives you a higher level of type-safety.\">\n  It gives you a higher level of type-safety.\n</FeedbackBlock>\n\nGenerate Code Samples [#generate-code-samples]\n\n<FeedbackBlock id=\"85a4e34e6e78b5fa\" body=\"Generate custom code samples for each API endpoint.\">\n  Generate custom code samples for each API endpoint.\n</FeedbackBlock>\n\n```ts\nimport { openapi } from '@/lib/openapi';\nimport { createAPIPage } from 'fumadocs-openapi/ui';\n\nexport const APIPage = createAPIPage(openapi, {\n  generateCodeSamples(endpoint) {\n    return [\n      {\n        id: 'js',\n        lang: 'js',\n        label: 'JavaScript SDK',\n        source: \"console.log('hello')\",\n      },\n      // or to disable the default code samples\n      // set `source: false`\n      {\n        id: 'curl',\n        lang: 'bash',\n        source: false,\n      },\n    ];\n  },\n});\n```\n\n<FeedbackBlock id=\"79c8fb0aa8d3db2f\" body=\"In addition, you can also specify code samples via OpenAPI schema.\">\n  In addition, you can also specify code samples via OpenAPI schema.\n</FeedbackBlock>\n\n```yaml\npaths:\n  /plants:\n    get:\n      x-codeSamples:\n        - lang: js\n          label: JavaScript SDK\n          source: |\n            const planter = require('planter');\n            planter.list({ unwatered: true });\n```\n\nMedia Adapters [#media-adapters]\n\n<FeedbackBlock id=\"6c333e36e7cb8186\" body=\"You can create a media adapter to support other media types in API pages, a media adapter implements:\">\n  You can create a media adapter to support other media types in API pages, a media adapter implements:\n</FeedbackBlock>\n\n<FeedbackBlock id=\"5560886b969423de\" body=\"Converting value into fetch() body compatible with corresponding media type.Generate code example based on different programming language/tool.\">\n  * Converting value into `fetch()` body compatible with corresponding media type.\n  * Generate code example based on different programming language/tool.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"bb143dcaf94e1bf5\" body=\"Put your media adapters in a separate file.\">\n  Put your media adapters in a separate file.\n</FeedbackBlock>\n\n```ts title=\"lib/media-adapters.ts\" twoslash\nimport type { MediaAdapter } from 'fumadocs-openapi';\n\nexport const mediaAdapters: Record<string, MediaAdapter> = {\n  // example: custom `application/json\n  'application/json': {\n    encode(data) {\n      return JSON.stringify(data.body);\n    },\n    // returns code that inits a `body` variable, used for request body\n    generateExample(data, ctx) {\n      if (ctx.lang === 'js') {\n        return `const body = \"hello world\"`;\n      }\n\n      if (ctx.lang === 'python') {\n        return `body = \"hello world\"`;\n      }\n\n      if (ctx.lang === 'go' && 'addImport' in ctx) {\n        ctx.addImport('strings');\n\n        return `body := strings.NewReader(\"hello world\")`;\n      }\n    },\n  },\n};\n```\n\n<FeedbackBlock id=\"c5bb74d072a45d29\" body=\"Pass the adapter to both client & server configs.\">\n  Pass the adapter to both client & server configs.\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"components/api-page.tsx\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"components/api-page.tsx\">\n      components/api-page.tsx\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"components/api-page.client.tsx\">\n      components/api-page.client.tsx\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"components/api-page.tsx\">\n    ```tsx\n    import { openapi } from '@/lib/openapi';\n    import { createAPIPage } from 'fumadocs-openapi/ui';\n    import { mediaAdapters } from '@/lib/media-adapters';\n    import client from './api-page.client';\n\n    export const APIPage = createAPIPage(openapi, {\n      client,\n      // [!code ++]\n      mediaAdapters,\n    });\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"components/api-page.client.tsx\">\n    ```tsx\n    'use client';\n    import { defineClientConfig } from 'fumadocs-openapi/ui/client';\n    import { mediaAdapters } from '@/lib/media-adapters';\n\n    export default defineClientConfig({\n      // [!code ++]\n      mediaAdapters,\n    });\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n";
